/**
 * Test flow for Inbound Email trigger
 * Tests: Email-based trigger with all email outputs
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_inbound_email_trigger_flow'],
        name: 'Test Inbound Email Trigger',
        description: 'Tests the Inbound Email trigger with email processing',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        {
            $id: Now.ID['27ff26c943d04d21b01998f473c0d10d'],
        },
        {
            email_conditions: 'subjectLIKEtest',
            target_table: 'incident',
            order: 100,
            stop_condition_evaluation: true,
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['7c5987372feb47939d7a9acff19da94b'],
            },
            {
                log_level: 'info',
                log_message: `Inbound Email: ${wfa.dataPill(_params.trigger.inbound_email, 'reference')}, Target Table: ${wfa.dataPill(_params.trigger.target_table_name, 'table_name')}, Body: ${wfa.dataPill(_params.trigger.body_text, 'string_full_utf8')}, Subject: ${wfa.dataPill(_params.trigger.subject, 'string_full_utf8')}, User: ${wfa.dataPill(_params.trigger.user, 'reference')}, Target Record: ${wfa.dataPill(_params.trigger.target_record, 'reference')}, From: ${wfa.dataPill(_params.trigger.from_address, 'string_full_utf8')}`,
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(_params.trigger.subject, 'string_full_utf8')}LIKEurgent`,
                annotation: 'Check if email is urgent',
                $id: Now.ID['85b5e2afca464a53aeef3f8efba7c594'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['ad6ef9c500034ffd96686f12791901ed'],
                    },
                    {
                        log_level: 'warn',
                        log_message: 'Urgent email received',
                    }
                )
            }
        )
    }
)

Flow(
    {
        $id: Now.ID['test_inbound_email_trigger_nested_flow'],
        name: 'Test Inbound Email Trigger - Multiple Data Pills',
        description: 'Tests the Inbound Email trigger with multiple data pills in log message',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['test_inbound_email_trigger_nested'] },
        {
            email_conditions: '^EQ',
            target_table: 'incident',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_inbound_email_log_nested'] },
            {
                log_level: 'info',
                log_message: `Table: ${wfa.dataPill(_params.trigger.target_table_name, 'table_name')}, Body: ${wfa.dataPill(_params.trigger.body_text, 'string_full_utf8')}, Subject: ${wfa.dataPill(_params.trigger.subject, 'string_full_utf8')}, User: ${wfa.dataPill(_params.trigger.user, 'reference')}`,
            }
        )
    }
)
